using System;
using System.Collections.Generic;
using UnityEngine;

namespace WordWorld.Data
{
    /// <summary>
    /// Vocabulary table (Assets/Data/vocabulary.json, generated by Assets/Languages/build_vocab.py),
    /// keyed by YOLOX class index. Turns a detected class into label text for a language and level.
    /// </summary>
    [AddComponentMenu("Word World/Vocabulary")]
    public sealed class Vocabulary : MonoBehaviour
    {
        [SerializeField] private TextAsset m_table;

        [Serializable]
        public sealed class LatinEntry
        {
            public string word;
            public string article;
            public string noun;
            public string gender;
            public bool plural;
            public string phrase;
            public string sentence;
            public string meaning;
            public string alternatives;
        }

        [Serializable]
        public sealed class ChineseEntry
        {
            public string characters;
            public string pinyin;
            public string measureWord;
            public string measureWordPinyin;
            public string phrase;
            public string phrasePinyin;
            public string sentence;
            public string sentencePinyin;
            public string meaning;
        }

        [Serializable]
        public sealed class Entry
        {
            public int classIndex;
            public string cocoLabel;
            public string category;
            public string roomFit;
            public bool enabled;
            public bool reviewed;
            public LatinEntry en;
            public LatinEntry es;
            public LatinEntry fr;
            public LatinEntry de;
            public ChineseEntry zh;
        }

        [Serializable]
        private sealed class Table
        {
            public Entry[] entries;
        }

        private readonly Dictionary<int, Entry> m_entries = new Dictionary<int, Entry>();

        private void Awake()
        {
            if (m_table == null)
            {
                Debug.LogError("[WordWorld.Vocabulary] no table assigned");
                return;
            }
            Table table = JsonUtility.FromJson<Table>(m_table.text);
            if (table?.entries == null) return;
            foreach (Entry entry in table.entries) m_entries[entry.classIndex] = entry;
            Debug.Log($"[WordWorld.Vocabulary] {m_entries.Count} entries");
        }

        public bool TryGet(int classId, out Entry entry) => m_entries.TryGetValue(classId, out entry) && entry != null;

        /// <summary>Disabled classes (e.g. giraffe) are never labeled even if the detector sees them.</summary>
        public bool IsEnabled(int classId) => TryGet(classId, out Entry entry) && entry.enabled;

        /// <summary>What a label shows: the main line, an optional pinyin ruby line above it, and
        /// whether the main line is pinyin (drawn in the accent colour).</summary>
        public struct LabelContent
        {
            public string Main;
            public string Ruby;
            public bool MainIsPinyin;
            /// <summary>English meaning (Chinese for English learners), shown under the word.</summary>
            public string Meaning;
        }

        /// <summary>
        /// Label content for a reading level (DESIGN.md section 3). Latin script: word with article,
        /// phrase, sentence. Mandarin: pinyin, characters with pinyin above, characters.
        /// </summary>
        public bool TryGetLabel(int classId, string language, int level, bool showPinyin, out LabelContent content)
        {
            content = default;
            if (!TryGet(classId, out Entry entry)) return false;
            if (language == "zh")
            {
                ChineseEntry zh = entry.zh;
                if (zh == null || string.IsNullOrEmpty(zh.characters)) return false;
                content.Meaning = zh.meaning;
                if (level <= 1)
                {
                    content.Main = zh.pinyin;
                    content.MainIsPinyin = true;
                }
                else
                {
                    content.Main = zh.characters;
                    if (level == 2 && showPinyin) content.Ruby = zh.pinyin;
                }
                return true;
            }
            LatinEntry latin = Latin(entry, language);
            if (latin == null || string.IsNullOrEmpty(latin.word)) return false;
            content.Meaning = latin.meaning;
            string text = level >= 3 ? latin.sentence : level == 2 ? latin.phrase : latin.word;
            content.Main = string.IsNullOrEmpty(text) ? latin.word : level >= 3 ? Wrap(text, 18, 2) : text;
            return true;
        }

        public static LatinEntry LatinFor(Entry entry, string language) => Latin(entry, language);

        /// <summary>Wraps at word boundaries, about <paramref name="lineLength"/> characters a line.</summary>
        public static string Wrap(string text, int lineLength, int maxLines)
        {
            if (string.IsNullOrEmpty(text) || text.Length <= lineLength) return text;
            var builder = new System.Text.StringBuilder(text.Length + maxLines);
            int lineStart = 0, lines = 1;
            string[] words = text.Split(' ');
            for (int i = 0; i < words.Length; i++)
            {
                int lineLengthSoFar = builder.Length - lineStart;
                if (i > 0)
                {
                    if (lineLengthSoFar + 1 + words[i].Length > lineLength && lines < maxLines)
                    {
                        builder.Append('\n');
                        lineStart = builder.Length;
                        lines++;
                    }
                    else builder.Append(' ');
                }
                builder.Append(words[i]);
            }
            return builder.ToString();
        }

        private static LatinEntry Latin(Entry entry, string language)
        {
            switch (language)
            {
                case "en": return entry.en;
                case "es": return entry.es;
                case "fr": return entry.fr;
                case "de": return entry.de;
                default: return null;
            }
        }
    }
}
